function h($x):string{return htmlspecialchars((string)$x,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function j($x):string{return json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR);}
function security():void{header_remove('X-Powered-By');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: strict-origin-when-cross-origin');header('X-Frame-Options: DENY');header('Permissions-Policy: camera=(), microphone=(), geolocation=()');header("Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'none'; frame-src 'none'; frame-ancestors 'none'; form-action 'self'");}
function start(string $title,string $desc,string $path,bool $noindex=false):void{security();if($noindex)header('X-Robots-Tag: noindex, follow');$url=ORIGIN.$path;$crumb=[['@type'=>'ListItem','position'=>1,'name'=>'Home','item'=>ORIGIN.'/'],['@type'=>'ListItem','position'=>2,'name'=>'Research timeline','item'=>ORIGIN.ROOT]];if($path!==ROOT)$crumb[]=['@type'=>'ListItem','position'=>3,'name'=>$title,'item'=>$url];?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=h($title)?> | Beyond Spacetime</title><meta name="description" content="<?=h($desc)?>"><meta name="robots" content="<?=$noindex?'noindex, follow':'index, follow'?>"><link rel="canonical" href="<?=h($url)?>"><meta property="og:title" content="<?=h($title)?>"><meta property="og:description" content="<?=h($desc)?>"><meta property="og:url" content="<?=h($url)?>"><meta property="og:image" content="<?=ORIGIN?>/evidence/assets/banner.webp"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/research/assets/research.css?v=1.5.0"><link rel="stylesheet" href="/timeline/assets/timeline.css?v=1.7.0"><script src="/timeline/assets/timeline.js?v=1.7.0" defer></script><script type="application/ld+json"><?=j(['@context'=>'https://schema.org','@graph'=>[['@type'=>'WebPage','name'=>$title,'description'=>$desc,'url'=>$url,'isPartOf'=>['@type'=>'WebSite','name'=>'Beyond Spacetime','url'=>ORIGIN.'/']],['@type'=>'BreadcrumbList','itemListElement'=>$crumb]]])?></script><link rel="stylesheet" href="/museum/assets/crossnav.css?v=2.2.1"></head><body><a class="skip" href="#main">Skip to content</a><header><div class="nav"><a class="brand" href="/"><img src="/evidence/assets/compass.png" alt="" width="46" height="46"><span>BEYOND<span class="gold">SPACETIME</span><small>THE EXPLAINER PROJECT</small></span></a><nav aria-label="Main navigation"><?php if(\bsp_legacy_available()):?><a href="/explore/">Explore 3D</a><?php endif;?><a href="/foundations/">Foundations</a><a href="/evidence/">Evidence</a><a href="/research/">Research</a><a href="/model-comparison/">Compare models</a><a href="/timeline/" <?=$path===ROOT?'aria-current="page"':''?>>Timeline</a></nav><a class="arc" href="https://arcsecs.com/read-scientific-paper/">Original research ↗</a></div></header><nav class="museum-crossnav" aria-label="Museum exhibits"><a href="/museum/">Museum</a><a href="/museum/search/">Search</a><a href="/foundations/">Foundations</a><a href="/evidence/">Evidence</a><a href="/research/">Workspace</a><a href="/model-comparison/">Compare</a><a href="/timeline/" aria-current="true">Timeline</a><a href="/global/">Languages</a><a href="/offline/">Offline</a><a href="/visualizations/">Visualize</a><a href="/knowledge-graph/">Graph</a><a href="/experiment-design/">Design</a><a href="/universal-time/">Time</a></nav><main class="wrap" id="main"><div class="crumb"><a href="/">Home</a> / <a href="/timeline/">Research timeline</a></div><?php }
function endpage():void{?><footer><div><strong>Beyond Spacetime · Discovery timeline</strong><p>Research history is not proof of a hypothesis. The complete research and publications remain on ArcSecs.</p></div><div><a href="/timeline/catalog.json">Machine catalog</a><a href="/timeline/method/">Source and API guide</a><a href="/timeline/sitemap.xml">Sitemap</a></div><div><a href="/evidence/">Evidence explorer</a><a href="/research/">Research workspace</a><a href="https://arcsecs.com/research-library/">ArcSecs research library ↗</a></div></footer></main></body></html><?php }
function options(array $items,string $current):void{?><option value="">All</option><?php foreach($items as $k=>$v):?><option value="<?=h($k)?>" <?=$k===$current?'selected':''?>><?=h($v)?></option><?php endforeach;}
function card(array $r):void{?><article class="timeline-item" data-track="<?=h($r['track'])?>" data-branch="<?=h($r['branch'])?>" data-status="<?=h($r['status'])?>" data-search="<?=h(implode(' ',[$r['id'],$r['title'],$r['original_title']??'',$r['summary'],$r['branch'],$r['date']??'']))?>"><div class="time-marker"><span><?=h(date_label($r))?></span><small><?=h($r['branch'])?></small></div><div class="panel time-card"><span class="status-label <?=h($r['status'])?>"><?=h(catalog()['statuses'][$r['status']])?></span><h3><a href="/timeline/record/<?=h($r['id'])?>/"><?=h($r['title'])?></a></h3><p><?=h($r['summary'])?></p><div class="time-links"><a href="/timeline/record/<?=h($r['id'])?>/">Inspect record →</a><button class="secondary pin-record" type="button" data-id="<?=h($r['id'])?>" hidden aria-pressed="false">Pin for comparison</button></div></div></article><?php }
function home():void{$err='';try{$f=filters($_GET);$selected=select($f);}catch(\InvalidArgumentException $e){http_response_code(400);$err=$e->getMessage();$f=filters([]);$selected=[];}start('Interactive scientific discovery timeline','Explore the 41 working reports, six manuscript editions, historical scientific references and conditional research milestones.',ROOT,!empty($_GET));?><section class="intro timeline-hero"><span class="eyebrow gold">V1.7 · RESEARCH HISTORY</span><h1>Follow the evolution of the science.</h1><p class="lead">Trace the questions, proposed mechanisms, failed controls and numerical developments behind BEYOND SPACETIME. Explore four distinct tracks, and follow each record back to its source.</p><div class="actions"><a class="button" href="#timeline-filters">Explore the timeline</a><a class="button secondary" href="/timeline/method/">Understand the evidence</a></div></section><div class="stats"><div><strong>41</strong><span>Working reports</span></div><div><strong>6</strong><span>Manuscript editions</span></div><div><strong>7</strong><span>Literature references</span></div><div><strong>7</strong><span>Model milestones</span></div></div><section class="notice"><strong>Read the dates carefully.</strong> Reports are shown in numbered archive order, not as dated discoveries. Edition dates come from manuscript metadata; reference years come from the Review 6.0 bibliography. Numerical checks do not establish empirical validation.</section><section class="panel section" id="timeline-filters"><h2>Find a research thread</h2><form id="timeline-filter" method="get" action="/timeline/"><div class="timeline-fields"><label>Search titles or topics<input name="q" type="search" maxlength="160" value="<?=h($f['q'])?>" placeholder="Photon, wall, clocks…"></label><label>Track<select name="track"><?php options(catalog()['tracks'],$f['track']);?></select></label><label>Research branch<select name="branch"><?php options(array_combine(branches(),branches()),$f['branch']);?></select></label><label>Scientific classification<select name="status"><?php options(catalog()['statuses'],$f['status']);?></select></label></div><div class="actions"><button type="submit">Apply filters</button><a class="button secondary" href="/timeline/">Reset</a><a class="button secondary" href="/timeline/catalog.json">Full JSON catalog</a></div></form><?php if($err):?><p role="alert"><?=h($err)?></p><?php endif;?><p id="timeline-count" role="status" class="muted"><?=count($selected)?> of <?=count(records())?> records</p></section><section class="panel" id="compare-dock"><h2>Compare two records</h2><p class="muted">Compare source lineage, assumptions and research status — not incompatible numerical quantities.</p><form method="get" action="/timeline/compare/"><div class="compare-fields"><?php foreach(['a'=>'Record A','b'=>'Record B'] as $k=>$label):?><label><?=h($label)?><select required name="<?=$k?>" id="compare-<?=$k?>"><option value="">Select a record</option><?php foreach(records() as $r):?><option value="<?=h($r['id'])?>" <?=($k==='a'&&($_GET['a']??null)===$r['id'])?'selected':''?>><?=h(strtoupper($r['id']).' · '.$r['title'])?></option><?php endforeach;?></select></label><?php endforeach;?></div><div class="actions"><button>Compare records</button><button type="button" class="secondary" id="clear-pins" hidden>Clear selection</button></div><p id="pin-status" role="status"></p></form></section><section class="section"><div class="section-heading"><h2>Research timeline</h2><a id="filtered-json" href="/timeline/api/?<?=h(http_build_query($f))?>">Export visible records (JSON)</a></div><?php foreach(catalog()['tracks'] as $k=>$label):$rows=array_values(array_filter($selected,fn($r)=>$r['track']===$k));?><section class="timeline-track" data-group="<?=h($k)?>" <?=$rows?'':'hidden'?>><h2><?=h($label)?></h2><p class="muted"><?=h(['references'=>'Publication years as cited in Review 6.0.','reports'=>'Archive order; original report titles are retained in each detail record.','reviews'=>'Dates as printed in manuscript metadata.','milestones'=>'Ordered by associated review, not discovery timestamp.'][$k])?></p><?php foreach($rows as $r)card($r);?></section><?php endforeach;?><p id="empty-timeline" <?=$selected?'hidden':''?>>No matching records. Try broader filters or reset.</p></section><?php endpage();}
function record_page(string $id):void{$r=records()[$id];[$prev,$next]=adjacent($r);start($r['title'],$r['summary'],ROOT.'record/'.$id.'/');?><section class="intro"><span class="eyebrow gold"><?=h(catalog()['tracks'][$r['track']])?> · <?=h(date_label($r))?></span><h1><?=h($r['title'])?></h1><p class="lead"><?=h($r['summary'])?></p><span class="status-label <?=h($r['status'])?>"><?=h(catalog()['statuses'][$r['status']])?></span></section><div class="timeline-detail"><article class="panel"><h2>What this record establishes</h2><p><?=h($r['summary'])?></p><h2>Scientific limits</h2><p><?=h($r['limitation'])?></p><h2>Chronology and provenance</h2><p><?=h($r['date_note'])?></p><?php if(isset($r['original_title'])):?><p><strong>Original report heading:</strong> <?=h($r['original_title'])?></p><?php endif;?><dl><dt>Source file</dt><dd class="source-path"><?=h($r['source']['path'])?></dd><dt>SHA-256 of supplied source bytes</dt><dd><code class="digest"><?=h($r['source']['sha256'])?></code></dd></dl><p class="muted">The source hash identifies the archived bytes, not a live URL or a proof of authenticity.</p><a class="button" href="<?=h($r['source']['url'])?>">Open original source ↗</a> <a href="https://arcsecs.com/research-library/">ArcSecs library ↗</a></article><aside class="panel"><h2>Continue the investigation</h2><?php foreach($r['related'] as $l):?><p><a href="<?=h($l['url'])?>"><?=h($l['label'])?> →</a></p><?php endforeach;?><p><a href="/timeline/api/?id=<?=h($id)?>">Machine-readable record</a></p><p><a href="/timeline/?branch=<?=h(rawurlencode($r['branch']))?>">All <?=h($r['branch'])?> records</a></p><p><a href="/timeline/?a=<?=h($id)?>#compare-dock">Compare with another record</a></p></aside></div><nav class="sequence-nav" aria-label="Adjacent records"><?php if($prev):?><a class="button secondary" href="/timeline/record/<?=h($prev['id'])?>/">← <?=h($prev['title'])?></a><?php endif;?><a href="/timeline/">All records</a><?php if($next):?><a class="button secondary" href="/timeline/record/<?=h($next['id'])?>/"><?=h($next['title'])?> →</a><?php endif;?></nav><?php endpage();}
function comparison_page():void{if(!isset($_GET['a'])&&!isset($_GET['b'])){start('Compare research records','Choose two different research records.',ROOT.'compare/',true);?><section class="intro"><h1>Compare research records</h1><p>Select two records to inspect their scope, limitations and provenance.</p></section><form class="panel" method="get" action="/timeline/compare/"><?php foreach(['a'=>'First record','b'=>'Second record'] as $key=>$label):?><label><?=h($label)?><select name="<?=$key?>" required><option value="">Choose a record</option><?php foreach(records() as $id=>$record):?><option value="<?=h($id)?>"><?=h($record['title'])?></option><?php endforeach;?></select></label><?php endforeach;?><button class="button" type="submit">Compare records</button></form><?php endpage();return;}try{$pair=compare($_GET);}catch(\InvalidArgumentException $e){http_response_code(400);start('Compare research records','Select two different research records.',ROOT.'compare/',true);?><section class="intro"><h1>Choose two different records</h1><p><?=h($e->getMessage())?></p><a href="/timeline/#compare-dock">Return to the selector</a></section><?php endpage();return;}start('Compare research records','Compare scientific status and provenance of two selected records.',ROOT.'compare/',true);?><section class="intro"><span class="eyebrow gold">SOURCE COMPARISON</span><h1>Two records, two evidence contexts.</h1><p class="lead">This is an editorial comparison, not a numerical fit or proof that two mechanisms are equivalent.</p></section><div class="compare-fields"><?php foreach($pair as $r):?><article class="panel"><span class="eyebrow"><?=h(date_label($r))?></span><h2><?=h($r['title'])?></h2><span class="status-label <?=h($r['status'])?>"><?=h(catalog()['statuses'][$r['status']])?></span><h3>Research scope</h3><p><?=h($r['summary'])?></p><h3>Limits</h3><p><?=h($r['limitation'])?></p><h3>Date meaning</h3><p><?=h($r['date_note'])?></p><a href="/timeline/record/<?=h($r['id'])?>/">Inspect provenance →</a></article><?php endforeach;?></div><div class="actions"><a class="button" href="/timeline/api/?a=<?=h($pair[0]['id'])?>&amp;b=<?=h($pair[1]['id'])?>">Export pair (JSON)</a><a class="button secondary" href="/timeline/#compare-dock">Choose another pair</a></div><?php endpage();}
function method_page():void{start('Timeline sources and machine interface','Documentation of the four timeline tracks, source hashes, chronology and read-only JSON interface.',ROOT.'method/');?><section class="intro"><span class="eyebrow gold">TRACEABLE SCIENTIFIC HISTORY</span><h1>Read the history, not just the conclusion.</h1><p class="lead"><?=h(catalog()['scope'])?></p></section><section class="panel"><h2>Four complementary tracks</h2><p>Working reports use archive numbering. Review editions use the date in their manuscript front matter. Literature entries retain cited publication years. Milestones use the associated review date, not an invented date of discovery.</p><p>All titles of numbered reports are preserved in their detailed records. Display labels are concise editorial summaries. Historical descriptions do not override the current twelve-foundation charter or corrected Review 6.0.</p><h2>Machine-readable access</h2><p><a href="/timeline/catalog.json">GET /timeline/catalog.json</a> — all records and status vocabulary.</p><p><a href="/timeline/api/?track=milestones">GET /timeline/api/?track=milestones</a> — filter by track, branch, status and optional q (up to 160 bytes).</p><p><a href="/timeline/api/?id=review-6">GET /timeline/api/?id=review-6</a> — individual record.</p><p><a href="/timeline/api/?a=review-5&amp;b=review-6">GET /timeline/api/?a=review-5&amp;b=review-6</a> — two distinct records.</p><p>Read-only JSON; no new solver, persistent state or AG-UI claims. For executable multi-case investigations use <a href="/research/protocol/">the existing research protocol</a>.</p><h2>Limitations</h2><p>Source paths and SHA-256 identify the exact supplied archived files. Public URLs may change; links to earlier editions lead to the current publication reader as a gateway. No private memory, source manuscript, book download or complete report is copied. External references and live links have not been independently reverified in this round.</p></section><?php endpage();}
